import { fromJS } from 'immutable';
import {
  checkAllScoresArePopulated,
  generateDefaultScores,
  getDefaultScoresByType,
  ITEM_TYPES,
} from '../../';

describe('Scoring Utility', () => {
  it('generateDefaultScores works', () => {
    const result = generateDefaultScores(3);
    expect(result).toEqual([
      {
        resultDouble: 1,
        score: 1,
      },
      {
        resultDouble: 2,
        score: 2,
      },
      {
        resultDouble: 3,
        score: 3,
      },
    ]);
  });

  it('generateDefaultScores works with override', () => {
    const result = generateDefaultScores(3, null);
    expect(result).toEqual([
      {
        resultDouble: 1,
        score: null,
      },
      {
        resultDouble: 2,
        score: null,
      },
      {
        resultDouble: 3,
        score: null,
      },
    ]);
  });

  it('getDefaultScoresByType works for YesNo type', () => {
    const result = getDefaultScoresByType(ITEM_TYPES.YES_NO);
    expect(result).toEqual([
      {
        resultDouble: 0,
        score: 0,
      },
      {
        resultDouble: 1,
        score: 1,
      },
    ]);
  });

  it('getDefaultScoresByType works for Rating_1_5 type', () => {
    const result = getDefaultScoresByType(ITEM_TYPES.RATING_1_5);
    expect(result).toEqual([
      {
        resultDouble: 1,
        score: 1,
      },
      {
        resultDouble: 2,
        score: 2,
      },
      {
        resultDouble: 3,
        score: 3,
      },
      {
        resultDouble: 4,
        score: 4,
      },
      {
        resultDouble: 5,
        score: 5,
      },
    ]);
  });

  it('getDefaultScoresByType works for Rating_1_10 type', () => {
    const result = getDefaultScoresByType(ITEM_TYPES.RATING_1_10);
    expect(result).toEqual([
      {
        resultDouble: 1,
        score: 1,
      },
      {
        resultDouble: 2,
        score: 2,
      },
      {
        resultDouble: 3,
        score: 3,
      },
      {
        resultDouble: 4,
        score: 4,
      },
      {
        resultDouble: 5,
        score: 5,
      },
      {
        resultDouble: 6,
        score: 6,
      },
      {
        resultDouble: 7,
        score: 7,
      },
      {
        resultDouble: 8,
        score: 8,
      },
      {
        resultDouble: 9,
        score: 9,
      },
      {
        resultDouble: 10,
        score: 10,
      },
    ]);
  });

  it('getDefaultScoresByType returns null scores for unsupported types', () => {
    const result = getDefaultScoresByType(ITEM_TYPES.CHECKMARK);
    expect(result).toBeNull();
  });

  it('checkAllScoresArePopulated returns true when scores are complete', () => {
    expect(
      checkAllScoresArePopulated([
        {
          resultDouble: 0,
          score: 0,
        },
        {
          resultDouble: 1,
          score: 2,
        },
      ]),
    ).toBe(true);
  });

  it('checkAllScoresArePopulated returns false when no scores', () => {
    expect(checkAllScoresArePopulated()).toBe(false);
  });

  it('checkAllScoresArePopulated returns false when scores are incomplete', () => {
    expect(
      checkAllScoresArePopulated([
        {
          resultDouble: 0,
          score: 0,
        },
        {
          resultDouble: 1,
          score: null,
        },
      ]),
    ).toBe(false);
  });

  it('checkAllScoresArePopulated works for Lists', () => {
    expect(
      checkAllScoresArePopulated(
        fromJS([
          {
            resultDouble: 0,
            score: 0,
          },
          {
            resultDouble: 1,
            score: 2,
          },
        ]),
      ),
    ).toBe(true);
  });
});
